-- Guides module RPCs.

create or replace function public.fetch_guide_profile(target_id uuid default null)
returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(gi) from public.guide_info gi
  where gi.id = coalesce(target_id, auth.uid())
$$;

create or replace function public.review_guide(
  guide_id uuid,
  rating numeric,
  review_text text default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  review_id uuid;
begin
  if uid is null then raise exception 'not authenticated'; end if;
  insert into public.guide_reviews (guide_id, reviewer_id, rating, review_text)
  values (review_guide.guide_id, uid, review_guide.rating, review_guide.review_text)
  returning id into review_id;
  update public.guides g
  set avg_rating = (
    select coalesce(avg(r.rating), 0)
    from public.guide_reviews r
    where r.guide_id = g.id
  )
  where g.id = review_guide.guide_id;
  return review_id;
end $$;

create or replace function public.get_guides_for_destination(
  lat double precision,
  lon double precision,
  result_limit int default 20
)
returns setof public.guide_info
language sql stable security definer set search_path = public as $$
  select gi.*
  from public.guide_info gi
  join public.guide_service_areas sa on sa.guide_id = gi.id
  where st_dwithin(
    sa.location,
    st_setsrid(st_makepoint(lon, lat), 4326)::geography,
    sa.radius_meters
  )
  and (gi->>'is_available')::boolean = true
  and (gi->>'is_suspended')::boolean = false
  order by gi.avg_rating desc
  limit result_limit
$$;

create or replace function public.get_suspended_guides()
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(to_jsonb(sg) order by sg.suspended_at desc), '[]'::jsonb)
  from public.suspended_guides sg
  where sg.lifted_at is null
$$;

-- ==== sql/rpc/users.sql ====
-- Users module RPCs.

create or replace function public.fetch_profile(target_id uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  resolved_id uuid := coalesce(target_id, auth.uid());
  result jsonb;
begin
  if resolved_id is null then
    raise exception 'not authenticated';
  end if;
  select to_jsonb(p) into result from public.profiles p where p.id = resolved_id;
  if result is null then
    raise exception 'profile not found';
  end if;
  -- Redact home_location into lat/lon jsonb for the client.
  if result ? 'home_location' then
    result := jsonb_set(
      result,
      '{home_location}',
      case
        when (select home_location is null from public.profiles where id = resolved_id) then 'null'::jsonb
        else (
          select jsonb_build_object(
            'latitude', st_y(home_location::geometry),
            'longitude', st_x(home_location::geometry)
          )
          from public.profiles where id = resolved_id
        )
      end
    );
  end if;
  return result;
end $$;

create or replace function public.is_username_available(username text)
returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (select 1 from public.profiles p where p.username = is_username_available.username);
$$;

create or replace function public.complete_onbording(
  first_name text,
  last_name text,
  username text,
  middle_name text default null,
  phone_number text default null,
  emergency_contact text default null,
  avatar_url text default null,
  home_location jsonb default null,
  home_location_name text default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  home geography;
begin
  if uid is null then raise exception 'not authenticated'; end if;
  if home_location is not null then
    home := st_setsrid(
      st_makepoint(
        (home_location->>'longitude')::double precision,
        (home_location->>'latitude')::double precision
      ),
      4326
    )::geography;
  end if;
  insert into public.profiles (
    id, first_name, middle_name, last_name, username,
    phone_number, emergency_contact, avatar_url,
    home_location, home_location_name, is_onboarding_complete
  )
  values (
    uid, first_name, middle_name, last_name, username,
    phone_number, emergency_contact, avatar_url,
    home, home_location_name, true
  )
  on conflict (id) do update set
    first_name = excluded.first_name,
    middle_name = excluded.middle_name,
    last_name = excluded.last_name,
    username = excluded.username,
    phone_number = excluded.phone_number,
    emergency_contact = excluded.emergency_contact,
    avatar_url = excluded.avatar_url,
    home_location = excluded.home_location,
    home_location_name = excluded.home_location_name,
    is_onboarding_complete = true,
    updated_at = now();
  return public.fetch_profile(uid);
end $$;

-- ==== sql/admin/rpc/admin_analytics.sql ====
-- Admin analytics RPCs.

create or replace function public.build_admin_analytics_payload(days int default 30)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare result jsonb;
begin
  perform public._assert_admin();
  select jsonb_build_object(
    'id', uuid_generate_v4(),
    'type', 'system_overview',
    'payload', jsonb_build_object(
      'window_days', days,
      'total_users', (select count(*) from public.profiles),
      'new_users', (
        select count(*) from public.profiles
        where created_at > now() - (days || ' days')::interval
      ),
      'new_bookings', (
        select count(*) from public.guide_bookings
        where hired_at > now() - (days || ' days')::interval
      ),
      'payment_volume', (
        select coalesce(sum(amount), 0) from public.payment_logs
        where status = 'succeeded'
          and created_at > now() - (days || ' days')::interval
      )
    ),
    'captured_at', now()
  ) into result;
  return result;
end $$;

create or replace function public.capture_admin_analytics_snapshot(
  type text,
  days int default 30
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  new_id uuid;
  payload jsonb;
begin
  perform public._assert_admin();
  payload := public.build_admin_analytics_payload(days);
  insert into public.admin_analytics (type, payload)
  values (type, payload)
  returning id into new_id;
  return new_id;
end $$;

create or replace function public.capture_all_admin_analytics_snapshots()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  types text[] := array['system_overview'];
  t text;
  ids uuid[] := '{}';
begin
  perform public._assert_admin();
  foreach t in array types loop
    ids := ids || public.capture_admin_analytics_snapshot(t);
  end loop;
  return jsonb_build_object('captured_ids', to_jsonb(ids));
end $$;

create or replace function public.run_admin_analytics_midnight_job()
returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.capture_all_admin_analytics_snapshots();
end $$;

create or replace function public.schedule_admin_analytics_midnight_job()
returns text
language plpgsql security definer set search_path = public as $$
begin
  perform cron.schedule(
    'admin_analytics_midnight',
    '0 0 * * *',
    $job$ select public.run_admin_analytics_midnight_job(); $job$
  );
  return 'admin_analytics_midnight';
end $$;

